INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33861, 'Genesis 20:7', 'Genesis', 20, 7, 'اوس هغه ښځه بېرته خپل مېړه ته ورکړه. هغه نبي دی او هغه به ستا دپاره دعا وکړي، ترڅو ژوندی پاتې شې. خو که چېرې هغه بېرته ورنه کړې، په دې پوه شه چې ته او ستا ټول خلک به مړه شئ.»', 'اوس هغه شجه بېرته خپل مېره ته ورکره. هغه نبی دی او هغه به ستا دپاره دعا وکری، ترچو ژوندی پاتې شې. خو که چېرې هغه بېرته ورنه کرې، په دې پوه شه چې ته او ستا تول خلک به مره شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33862, 'Genesis 20:8', 'Genesis', 20, 8, 'سبا سهار وختي ابي‌ملک خپل ټول درباریان راوغوښتل او څه چې پېښ شوي وو هغوی ته یې بیان کړل او هغوی ډېر ووېرېدل.', 'سبا سهار وختی ابی‌ملک خپل تول درباریان راوغوشتل او چه چې پېش شوی وو هغوی ته یې بیان کرل او هغوی دېر ووېرېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33863, 'Genesis 20:9', 'Genesis', 20, 9, 'بیا ابي‌ملک ابراهیم راوغوښت او پوښتنه یې ترې وکړه: «زمونږ سره دې څه وکړل؟ ما ستا سره څه بد کړي وو چې داسې لوی مصیبت دې په ما او زما په پاچاهۍ باندې راوست؟ تا زما سره داسې کار وکړ چې د کولو نه ؤ.»', 'بیا ابی‌ملک ابراهیم راوغوشت او پوشتنه یې ترې وکره: «زمونز سره دې چه وکرل؟ ما ستا سره چه بد کری وو چې داسې لوی مصیبت دې په ما او زما په پاچاهی باندې راوست؟ تا زما سره داسې کار وکر چې د کولو نه و.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33864, 'Genesis 20:10', 'Genesis', 20, 10, 'بیا ابي‌ملک د ابراهیم څخه پوښتنه وکړه: «داسې کار دې ولې وکړ؟»', 'بیا ابی‌ملک د ابراهیم چخه پوشتنه وکره: «داسې کار دې ولې وکر؟»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33865, 'Genesis 20:11', 'Genesis', 20, 11, 'ابراهیم ځواب ورکړ: «ما فکر وکړ چې د دې ځای خلک د خدای څخه نه وېریږي او ما به د خپلې ښځې په خاطر ووژني.', 'ابراهیم جواب ورکر: «ما فکر وکر چې د دې جای خلک د خدای چخه نه وېریزی او ما به د خپلې شجې په خاطر ووژنی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33866, 'Genesis 20:12', 'Genesis', 20, 12, 'هغه په رښتیا سره زما خور ده، هغه زما ناسکه خور ده. هغه زما د پلار لور ده، خو زما د مور لور نه ده او ما د هغې سره واده کړی دی.', 'هغه په رشتیا سره زما خور ده، هغه زما ناسکه خور ده. هغه زما د پلار لور ده، خو زما د مور لور نه ده او ما د هغې سره واده کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33867, 'Genesis 20:13', 'Genesis', 20, 13, 'کله چې خدای زه د خپل پلار د کور څخه پردي هېواد ته ولېږلم، ما هغې ته وویل: ‹دا به زما سره ستا وفاداري وي چې مونږ هرځای ته لاړ شو، زما په هکله به وایې چې هغه زما ورور دی.›»', 'کله چې خدای زه د خپل پلار د کور چخه پردی هېواد ته ولېزلم، ما هغې ته وویل: ‹دا به زما سره ستا وفاداری وی چې مونز هرجای ته لار شو، زما په هکله به وایې چې هغه زما ورور دی.›»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33868, 'Genesis 20:14', 'Genesis', 20, 14, 'نو ابي‌ملک ابراهیم ته پسونه او غویان، غلامان او وینځې ورکړل او د هغه ښځه ساره یې بېرته هغه ته وسپارله.', 'نو ابی‌ملک ابراهیم ته پسونه او غویان، غلامان او وینجې ورکرل او د هغه شجه ساره یې بېرته هغه ته وسپارله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33869, 'Genesis 20:15', 'Genesis', 20, 15, 'ابي‌ملک وویل: «زما ټوله ځمکه ستا په مخکې ده، هرځای چې ستا خوښ وي هلته واوسېږه.»', 'ابی‌ملک وویل: «زما توله جمکه ستا په مخکې ده، هرجای چې ستا خوش وی هلته واوسېزه.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33870, 'Genesis 20:16', 'Genesis', 20, 16, 'هغه ساره ته وویل: «زه ستا ورور ته د سپینو زرو زر سیکې ورکوم، ترڅو هغو ټولو خلکو ته چې ستا سره دي دا ثابته شي چې ته بې‌ګناه یې او هر یو په دې باندې پوه شي چې تا کومه غلطي نه ده کړې.»', 'هغه ساره ته وویل: «زه ستا ورور ته د سپینو زرو زر سیکې ورکوم، ترچو هغو تولو خلکو ته چې ستا سره دی دا ثابته شی چې ته بې‌ګناه یې او هر یو په دې باندې پوه شی چې تا کومه غلطی نه ده کرې.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_20_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33871, 'Job 25:1', 'Job', 25, 1, 'بيا شوحى بِلداد جواب ورکړو،', 'بیا شوحی بلداد جواب ورکرو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_25_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33872, 'Job 25:2', 'Job', 25, 2, '”اختيار او يره د خُدائ پاک سره دى، هغه په آسمانى بادشاهۍ کښې امن قائموى.', '”اختیار او یره د خدای پاک سره دی، هغه په اسمانی بادشاهی کشې امن قایموی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_25_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33873, 'Job 25:3', 'Job', 25, 3, 'د هغۀ آسمانى لښکر څوک شمارلے شى؟ د هغۀ رڼا په چا باندې نۀ ځليږى؟', 'د هغۀ اسمانی لشکر چوک شمارلے شی؟ د هغۀ رنا په چا باندې نۀ جلیزی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_25_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33874, 'Job 25:4', 'Job', 25, 4, 'نو بنى آدم د خُدائ پاک په مخکښې څنګه صادق کېدے شى؟ څوک چې د مور نه پېدا شوے وى نو هغه کس څنګه صفا کېدے شى؟', 'نو بنی ادم د خدای پاک په مخکشې چنګه صادق کېدے شی؟ چوک چې د مور نه پېدا شوے وی نو هغه کس چنګه صفا کېدے شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_25_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33875, 'Job 25:5', 'Job', 25, 5, 'ګوره، د هغۀ په وړاندې ځلېدونکى سپوږمۍ او ستورى هيڅ هم نۀ دى.', 'ګوره، د هغۀ په وراندې جلېدونکی سپوزمی او ستوری هیچ هم نۀ دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_25_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33876, 'Job 25:6', 'Job', 25, 6, 'نو بيا انسان څۀ څيز دے يو مېږے کۀ يا يو چينجے؟ د خُدائ پاک په نظر کښې د يو انسان څۀ اهميت دے؟“', 'نو بیا انسان چۀ چیز دے یو مېزے کۀ یا یو چینجے؟ د خدای پاک په نظر کشې د یو انسان چۀ اهمیت دے؟“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_25_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33877, 'Isaiah 40:1', 'Isaiah', 40, 1, 'ستاسو خدای وایي: «ورکړئ تسلي زما غوره شوي قوم ته ورکړئ تسلي!', 'ستاسو خدای وایی: «ورکری تسلی زما غوره شوی قوم ته ورکری تسلی!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_001.mp3', 'https://drive.google.com/file/d/1gd7f_UKYeUotIzY6RysnBRD5gfQ8g82P/preview', 1761237837, 1761237837),
(33878, 'Isaiah 40:2', 'Isaiah', 40, 2, 'خبرې وکړئ په نرمه ژبه د اورشلیم خلکو سره او کړئ اعلان هغوی ته چې تېرې شوې مو دي د غلامۍ ورځې او ما بخښلي ګناهونه ستاسو ځکه هغوی ته مې ورکړې سزا د ګناهونو په بدل کې یو په دوه»', 'خبرې وکری په نرمه ژبه د اورشلیم خلکو سره او کری اعلان هغوی ته چې تېرې شوې مو دی د غلامی ورجې او ما بخشلی ګناهونه ستاسو جکه هغوی ته مې ورکرې سزا د ګناهونو په بدل کې یو په دوه»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_002.mp3', 'https://drive.google.com/uc?id=1n0zklVKMAm1idGl_UNOQVRhjxigEI1uj&export=download', 1761237837, 1761237837),
(33879, 'Isaiah 40:3', 'Isaiah', 40, 3, 'زه اواز اورم چې یو څوک وهي نارې: «لاره تیاره کړئ په دښته کې څښتن دپاره جوړه صحرا کې کړئ لویه او سیده لاره زمونږ د خدای دپاره', 'زه اواز اورم چې یو چوک وهی نارې: «لاره تیاره کری په دشته کې چشتن دپاره جوره صحرا کې کری لویه او سیده لاره زمونز د خدای دپاره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_003.mp3', 'https://drive.google.com/uc?id=1n3wsTaebM7JMQOoVuEgbU6sFidcwjblS&export=download', 1761237837, 1761237837),
(33880, 'Isaiah 40:4', 'Isaiah', 40, 4, 'شي به ډکه هره دره شي به هواره هره غونډۍ او غر او شي به هوار کنډ و کپر ځایونه', 'شی به دکه هره دره شی به هواره هره غوندی او غر او شی به هوار کند و کپر جایونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_004.mp3', 'https://drive.google.com/file/d/1W43VS1WfqYd4dEy078Y_7Et9ADjHQ7GM/preview', 1761237837, 1761237837),
(33881, 'Isaiah 40:5', 'Isaiah', 40, 5, 'بیا راښکاره به شي جلال د څښتن او ټول انسانان به یې یوځای وویني ځکه داسې ویلي دي خپله څښتن»', 'بیا راشکاره به شی جلال د چشتن او تول انسانان به یې یوجای ووینی جکه داسې ویلی دی خپله چشتن»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_005.mp3', 'https://drive.google.com/file/d/17s11tQsS9ec-B1payUxNrI45AYfRECil/preview', 1761237837, 1761237837),
(33882, 'Isaiah 40:6', 'Isaiah', 40, 6, 'یو اواز راځي او وایي: «یو پیغام اعلان کړه» ما پوښتنه وکړه: «کوم پیغام اعلان کړم؟» «دا اعلان وکړه چې د واښو په شان دي ټول انسانان زیات دوام نه کړي د هغوی ژوند له ځنګلي ګلانو', 'یو اواز راجی او وایی: «یو پیغام اعلان کره» ما پوشتنه وکره: «کوم پیغام اعلان کرم؟» «دا اعلان وکره چې د واشو په شان دی تول انسانان زیات دوام نه کری د هغوی ژوند له جنګلی ګلانو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_006.mp3', 'https://drive.google.com/file/d/1C60oSxt8WhgVVf8deCRXgFOquudMBn9n/preview', 1761237837, 1761237837),
(33883, 'Isaiah 40:7', 'Isaiah', 40, 7, 'څښتن چې کله په هغوی باندې نازل کړي باد واښه وچیږي او ګلان رژیږي هو، په رښتیا چې انسانان دي د واښو په شان', 'چشتن چې کله په هغوی باندې نازل کری باد واشه وچیزی او ګلان رژیزی هو، په رشتیا چې انسانان دی د واشو په شان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_007.mp3', 'https://drive.google.com/file/d/1wlO8WDFwuJO-8WUbqzFIa2mxRNWxAVuW/preview', 1761237837, 1761237837),
(33884, 'Isaiah 40:8', 'Isaiah', 40, 8, 'واښه وچیږي او ګلان رژیږي خو تل ترتله به وي ټینګ زمونږ د خدای کلام»', 'واشه وچیزی او ګلان رژیزی خو تل ترتله به وی تینګ زمونز د خدای کلام»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_008.mp3', 'https://drive.google.com/file/d/1Il0YCWBFXM_kY0KJmr8iBuygE-K-XUmI/preview', 1761237837, 1761237837),
(33885, 'Isaiah 40:9', 'Isaiah', 40, 9, 'ای صهیونه، وخېژه لوړ غره ته له هغه ځایه ورکړه زېری ای اورشلیمه، په لوړ اواز ورکړه خپل زېری پرته له وېرې ته اعلان کړه هغه د یهودا ښارو ته ووایه: «راروان دی ستاسو خدای»', 'ای صهیونه، وخېژه لور غره ته له هغه جایه ورکره زېری ای اورشلیمه، په لور اواز ورکره خپل زېری پرته له وېرې ته اعلان کره هغه د یهودا شارو ته ووایه: «راروان دی ستاسو خدای»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_009.mp3', 'https://drive.google.com/file/d/1BeNDlcfLgODJ5v2jnk__L3D4wJ3trz4C/preview', 1761237837, 1761237837),
(33886, 'Isaiah 40:10', 'Isaiah', 40, 10, 'ګوره، څښتن تعالی راځي او پاچاهي کوي د مټو په زور ګوره، راولي له خپله ځانه سره هغه ژغورل شوي خلک راروان دي هغوی هغه نه مخکې', 'ګوره، چشتن تعالی راجی او پاچاهی کوی د متو په زور ګوره، راولی له خپله جانه سره هغه ژغورل شوی خلک راروان دی هغوی هغه نه مخکې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah040_verse_010.mp3', 'https://drive.google.com/uc?id=1eUfREa5ickvdDFFFM9W6I-cKoZ0xmPEW&export=download', 1761237837, 1761237837),
